from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

from sqlglot import exp

from ai.ast.models import SQLMetadata


@dataclass
class RepairCandidate:
    """
    Represents a possible repair for a single invalid SQL object.
    """

    original: str
    replacement: str
    confidence: float
    reason: str


@dataclass
class RepairContext:
    """
    Carries everything required throughout the SQL repair pipeline.

    This object is progressively updated by each repair strategy.
    """

    # Original SQL generated by the LLM
    original_sql: str

    # Current working SQL (changes after every successful repair)
    current_sql: str

    # Parsed AST
    ast: Optional[exp.Expression] = None

    # Extracted metadata
    metadata: SQLMetadata = field(default_factory=SQLMetadata)

    # Current schema metadata
    schema_metadata: Dict[str, Any] = field(default_factory=dict)

    # Validation errors that triggered repair
    validation_errors: List[str] = field(default_factory=list)

    # Repair history
    applied_repairs: List[RepairCandidate] = field(default_factory=list)

    # Number of repair attempts
    repair_attempts: int = 0

    # Maximum attempts allowed
    max_attempts: int = 3